import { useEffect, useMemo, useState } from 'react'
import {
  AlertTriangle, ArrowDownRight, ArrowRight, ChevronRight, CircleHelp, Clock3,
  Copy, Flag, Footprints, HeartHandshake, Home, Info, Lightbulb, MapPin,
  Menu, Navigation, Phone, Plus, Radar, Route, Shield, ShieldAlert, ShieldCheck,
  Signal, Sparkles, Users, X,
} from 'lucide-react'
import { demoReports, routeOptions } from './data/demo'
import type { ReportCategory, RouteOption, SafetyReport, Severity, TrustedContact, Trip } from './types'

type Page = 'home' | 'route' | 'reports' | 'contacts' | 'score'
type Toast = { kind: 'success' | 'error'; message: string } | null

const reportCategories: ReportCategory[] = ['Poor lighting', 'Harassment', 'Suspicious activity', 'Unsafe crossing', 'Other']
const severityStyles: Record<Severity, string> = {
  Low: 'bg-sky-50 text-sky-800 ring-sky-200',
  Medium: 'bg-amber-50 text-amber-800 ring-amber-200',
  High: 'bg-rose-50 text-rose-800 ring-rose-200',
}

const makeId = () => globalThis.crypto?.randomUUID?.() ?? `${Date.now()}-${Math.random().toString(16).slice(2)}`

function App() {
  const [page, setPage] = useState<Page>('home')
  const [reports, setReports] = useState<SafetyReport[]>([])
  const [contacts, setContacts] = useState<TrustedContact[]>([])
  const [trip, setTrip] = useState<Trip | null>(null)
  const [toast, setToast] = useState<Toast>(null)
  const [sosOpen, setSosOpen] = useState(false)

  useEffect(() => {
    try {
      setReports(JSON.parse(localStorage.getItem('saferoute-reports') ?? '[]'))
      setContacts(JSON.parse(localStorage.getItem('saferoute-contacts') ?? '[]'))
    } catch {
      setToast({ kind: 'error', message: 'Saved demo data could not be loaded. You can still use SafeRoute.' })
    }
  }, [])

  const allReports = useMemo(() => [...reports, ...demoReports], [reports])
  const navigate = (next: Page) => {
    setPage(next)
    window.scrollTo({ top: 0, behavior: 'smooth' })
  }
  const showToast = (next: NonNullable<Toast>) => {
    setToast(next)
    window.setTimeout(() => setToast(null), 4400)
  }
  const createTrip = (start: string, destination: string, selected = routeOptions[0]) => {
    setTrip({ start, destination, route: selected })
    navigate('route')
    showToast({ kind: 'success', message: 'Route options updated using Community/Demo Safety Data.' })
  }
  const saveReport = (report: SafetyReport) => {
    const next = [report, ...reports]
    setReports(next)
    localStorage.setItem('saferoute-reports', JSON.stringify(next))
    showToast({ kind: 'success', message: 'Your community report has been saved and added to the map.' })
  }
  const saveContacts = (next: TrustedContact[]) => {
    setContacts(next)
    localStorage.setItem('saferoute-contacts', JSON.stringify(next))
  }

  return (
    <div className="min-h-screen bg-[#f8f8f4] text-ink selection:bg-lime selection:text-moss">
      <Header page={page} onNavigate={navigate} onSOS={() => setSosOpen(true)} />
      <main>
        {page === 'home' && <Landing onFind={createTrip} onNavigate={navigate} onSOS={() => setSosOpen(true)} />}
        {page === 'route' && <RoutePage trip={trip} reports={allReports} onFind={createTrip} onChangeRoute={(route) => trip && setTrip({ ...trip, route })} onReport={() => navigate('reports')} />}
        {page === 'reports' && <ReportsPage reports={allReports} onSubmit={saveReport} />}
        {page === 'contacts' && <ContactsPage contacts={contacts} onChange={saveContacts} onToast={showToast} />}
        {page === 'score' && <SafetyScorePage />}
      </main>
      <Footer onNavigate={navigate} />
      {sosOpen && <SOSModal contacts={contacts} onClose={() => setSosOpen(false)} onToast={showToast} />}
      {toast && <ToastMessage toast={toast} onClose={() => setToast(null)} />}
    </div>
  )
}

function Header({ page, onNavigate, onSOS }: { page: Page; onNavigate: (page: Page) => void; onSOS: () => void }) {
  const [menuOpen, setMenuOpen] = useState(false)
  const links: { id: Page; label: string }[] = [
    { id: 'home', label: 'Home' }, { id: 'route', label: 'Find route' }, { id: 'reports', label: 'Safety reports' },
    { id: 'contacts', label: 'Trusted contacts' }, { id: 'score', label: 'Safety score' },
  ]
  const select = (id: Page) => { onNavigate(id); setMenuOpen(false) }
  return (
    <header className="sticky top-0 z-40 border-b border-moss/10 bg-[#f8f8f4]/90 backdrop-blur-xl">
      <div className="mx-auto flex h-[72px] max-w-7xl items-center justify-between px-5 sm:px-8">
        <button onClick={() => select('home')} className="group flex items-center gap-2.5" aria-label="SafeRoute home">
          <span className="grid h-9 w-9 place-items-center rounded-xl bg-moss text-lime shadow-sm transition-transform group-hover:-rotate-6"><ShieldCheck size={21} /></span>
          <span className="text-xl font-extrabold tracking-tight text-moss">SafeRoute</span>
        </button>
        <nav className="hidden items-center gap-1 lg:flex" aria-label="Main navigation">
          {links.map((link) => <button key={link.id} onClick={() => select(link.id)} className={`rounded-lg px-3 py-2 text-sm font-semibold transition ${page === link.id ? 'bg-moss text-white' : 'text-moss/75 hover:bg-moss/5 hover:text-moss'}`}>{link.label}</button>)}
        </nav>
        <div className="flex items-center gap-2">
          <button onClick={onSOS} className="inline-flex min-h-10 items-center gap-2 rounded-xl bg-coral px-3.5 py-2 text-sm font-extrabold text-white shadow-sm transition hover:-translate-y-0.5 hover:bg-[#d85c50] focus:outline-none focus:ring-4 focus:ring-coral/25" aria-label="Open SOS emergency options"><Signal size={16} /> <span>SOS</span></button>
          <button onClick={() => setMenuOpen(!menuOpen)} className="grid h-10 w-10 place-items-center rounded-xl text-moss hover:bg-moss/5 lg:hidden" aria-label="Open menu" aria-expanded={menuOpen}>{menuOpen ? <X size={22} /> : <Menu size={22} />}</button>
        </div>
      </div>
      {menuOpen && <nav className="border-t border-moss/10 bg-[#f8f8f4] px-5 py-3 shadow-lg lg:hidden" aria-label="Mobile navigation">
        <div className="mx-auto grid max-w-7xl gap-1">{links.map((link) => <button key={link.id} onClick={() => select(link.id)} className={`rounded-xl px-4 py-3 text-left text-sm font-bold ${page === link.id ? 'bg-moss text-white' : 'text-moss hover:bg-moss/5'}`}>{link.label}</button>)}</div>
      </nav>}
    </header>
  )
}

function Landing({ onFind, onNavigate, onSOS }: { onFind: (start: string, destination: string) => void; onNavigate: (page: Page) => void; onSOS: () => void }) {
  return (
    <>
      <section className="relative overflow-hidden bg-moss pb-14 pt-12 sm:pb-20 sm:pt-20">
        <div className="absolute inset-0 dot-field opacity-50" />
        <div className="absolute -right-20 top-10 h-72 w-72 rounded-full bg-lime/10 blur-3xl" />
        <div className="absolute -left-20 bottom-0 h-56 w-56 rounded-full bg-teal-300/10 blur-3xl" />
        <div className="relative mx-auto grid max-w-7xl items-center gap-10 px-5 sm:px-8 lg:grid-cols-[1.05fr_.95fr]">
          <div className="max-w-2xl">
            <div className="mb-5 inline-flex items-center gap-2 rounded-full border border-lime/30 bg-lime/10 px-3 py-1.5 text-xs font-bold tracking-wide text-lime"><Sparkles size={14} /> COMMUNITY-FIRST SAFETY ASSISTANT</div>
            <h1 className="max-w-xl text-4xl font-black leading-[1.02] tracking-[-.045em] text-white sm:text-6xl">Choose a safer<br /><span className="text-lime">way home.</span></h1>
            <p className="mt-6 max-w-xl text-base leading-relaxed text-white/74 sm:text-lg">SafeRoute helps you make more informed route decisions using community safety reports, lighting and activity indicators.</p>
            <div className="mt-8 flex flex-wrap gap-3 text-sm font-semibold text-white/80"><span className="inline-flex items-center gap-2"><ShieldCheck className="text-lime" size={17} /> Transparent safety score</span><span className="inline-flex items-center gap-2"><Users className="text-lime" size={17} /> Community-powered</span></div>
          </div>
          <RouteSearch onFind={onFind} variant="hero" />
        </div>
      </section>

      <section className="mx-auto -mt-5 max-w-7xl px-5 sm:px-8">
        <div className="grid gap-px overflow-hidden rounded-2xl border border-moss/10 bg-moss/10 shadow-float md:grid-cols-3">
          <MiniStat icon={<Lightbulb size={21} />} title="Street context" text="Compare lighting and activity along each option." />
          <MiniStat icon={<Radar size={21} />} title="Community signals" text="See clearly labeled community safety reports nearby." />
          <MiniStat icon={<HeartHandshake size={21} />} title="Help within reach" text="Keep a trusted contact and SOS actions close by." />
        </div>
      </section>

      <section className="mx-auto grid max-w-7xl gap-8 px-5 py-20 sm:px-8 lg:grid-cols-[1fr_.8fr] lg:items-center">
        <div>
          <p className="eyebrow">HOW IT HELPS</p>
          <h2 className="mt-3 max-w-lg text-3xl font-black tracking-tight text-moss sm:text-4xl">More context before you step out.</h2>
          <p className="mt-4 max-w-xl text-base leading-relaxed text-ink/65">SafeRoute does not promise safety. It makes route choices easier to understand by bringing together the indicators that matter in the moment.</p>
          <div className="mt-7 grid gap-4 sm:grid-cols-2">
            <Feature icon={<Route size={19} />} title="Compare routes" text="Balance time, distance and safety context in one view." />
            <Feature icon={<Flag size={19} />} title="Add a report" text="Share an issue so the demo map and local community view update." />
          </div>
        </div>
        <aside className="rounded-3xl border border-moss/10 bg-white p-6 shadow-float sm:p-8">
          <div className="flex items-center justify-between"><span className="eyebrow">READY WHEN YOU ARE</span><span className="rounded-full bg-amber-50 px-3 py-1 text-xs font-bold text-amber-800">Demo Mode</span></div>
          <h3 className="mt-4 text-2xl font-extrabold tracking-tight text-moss">Choose what you need.</h3>
          <div className="mt-6 space-y-3">
            <button onClick={() => onNavigate('reports')} className="flex w-full items-center justify-between rounded-2xl border border-moss/10 p-4 text-left transition hover:border-moss/30 hover:bg-sage/30"><span><b className="block text-moss">Report an unsafe spot</b><small className="text-ink/55">Add a Community/Demo Safety Data report</small></span><ArrowRight className="text-moss" size={19} /></button>
            <button onClick={onSOS} className="flex w-full items-center justify-between rounded-2xl border border-coral/20 bg-rose-50 p-4 text-left transition hover:bg-rose-100"><span><b className="block text-rose-900">Emergency options</b><small className="text-rose-800/65">Call, share location, or contact someone you trust</small></span><Signal className="text-coral" size={19} /></button>
          </div>
        </aside>
      </section>
    </>
  )
}

function RouteSearch({ onFind, variant = 'plain' }: { onFind: (start: string, destination: string) => void; variant?: 'hero' | 'plain' }) {
  const [start, setStart] = useState('City Library')
  const [destination, setDestination] = useState('Harbor Station')
  const [error, setError] = useState('')
  const submit = (event: React.FormEvent) => {
    event.preventDefault()
    const cleanStart = start.trim(), cleanDestination = destination.trim()
    if (cleanStart.length < 2 || cleanDestination.length < 2) return setError('Enter both a start location and destination to compare routes.')
    if (/invalid|unknown/i.test(`${cleanStart} ${cleanDestination}`)) return setError('We could not recognise one of those locations. Try a nearby landmark or street name.')
    setError('')
    onFind(cleanStart, cleanDestination)
  }
  const hero = variant === 'hero'
  return <form onSubmit={submit} className={hero ? 'rounded-3xl border border-white/10 bg-white p-5 shadow-2xl sm:p-6' : 'rounded-2xl border border-moss/10 bg-white p-5'} noValidate>
    {hero && <div className="mb-5 flex items-start justify-between"><div><p className="text-sm font-extrabold text-moss">Plan a safer route</p><p className="mt-1 text-xs text-ink/55">Compare local route context in seconds.</p></div><span className="grid h-9 w-9 place-items-center rounded-xl bg-sage text-moss"><Navigation size={18} /></span></div>}
    <label className="block text-xs font-bold uppercase tracking-wider text-ink/50">Starting from</label>
    <div className="mt-1.5 flex items-center gap-2 rounded-xl border border-moss/15 bg-[#fcfcf9] px-3 focus-within:border-moss focus-within:ring-4 focus-within:ring-moss/10"><MapPin className="shrink-0 text-moss" size={18} /><input value={start} onChange={(e) => setStart(e.target.value)} placeholder="e.g. City Library" className="h-12 w-full bg-transparent text-sm font-semibold text-moss outline-none placeholder:text-ink/35" /></div>
    <div className="ml-[17px] h-4 border-l border-dashed border-moss/25" />
    <label className="block text-xs font-bold uppercase tracking-wider text-ink/50">Going to</label>
    <div className="mt-1.5 flex items-center gap-2 rounded-xl border border-moss/15 bg-[#fcfcf9] px-3 focus-within:border-moss focus-within:ring-4 focus-within:ring-moss/10"><span className="grid h-[18px] w-[18px] shrink-0 place-items-center rounded-full border-[5px] border-coral" /><input value={destination} onChange={(e) => setDestination(e.target.value)} placeholder="e.g. Harbor Station" className="h-12 w-full bg-transparent text-sm font-semibold text-moss outline-none placeholder:text-ink/35" /></div>
    {error && <p role="alert" className="mt-3 flex gap-2 rounded-lg bg-rose-50 px-3 py-2 text-xs font-semibold text-rose-800"><AlertTriangle size={15} className="shrink-0" />{error}</p>}
    <button type="submit" className="mt-5 inline-flex min-h-12 w-full items-center justify-center gap-2 rounded-xl bg-moss px-5 py-3 text-sm font-extrabold text-white transition hover:-translate-y-0.5 hover:bg-[#145146] focus:outline-none focus:ring-4 focus:ring-moss/25"><Route size={18} /> Find a safer route <ArrowRight size={17} /></button>
    {hero && <p className="mt-3 text-center text-[11px] leading-relaxed text-ink/45">Safety information uses clearly labeled Community/Demo Safety Data, not official safety guarantees.</p>}
  </form>
}

function RoutePage({ trip, reports, onFind, onChangeRoute, onReport }: { trip: Trip | null; reports: SafetyReport[]; onFind: (start: string, destination: string) => void; onChangeRoute: (route: RouteOption) => void; onReport: () => void }) {
  const selected = trip?.route ?? routeOptions[0]
  return <>
    <section className="border-b border-moss/10 bg-white py-10 sm:py-14"><div className="mx-auto max-w-7xl px-5 sm:px-8"><p className="eyebrow">ROUTE PLANNER</p><h1 className="mt-2 text-3xl font-black tracking-tight text-moss sm:text-4xl">Find your way with more context.</h1><div className="mt-7 max-w-4xl"><RouteSearch onFind={onFind} /></div></div></section>
    <section className="mx-auto max-w-7xl px-5 py-10 sm:px-8 lg:py-14">
      <div className="mb-6 flex flex-wrap items-center justify-between gap-3"><div><h2 className="text-2xl font-extrabold tracking-tight text-moss">Your route options</h2><p className="mt-1 text-sm text-ink/55">{trip ? <><b>{trip.start}</b> <ArrowRight className="mx-1 inline" size={14} /> <b>{trip.destination}</b></> : 'Try the demo trip or enter your locations above.'}</p></div><span className="rounded-full bg-amber-50 px-3 py-1.5 text-xs font-bold text-amber-800">Community/Demo Safety Data</span></div>
      <div className="grid gap-6 xl:grid-cols-[minmax(0,1.25fr)_390px]">
        <div className="space-y-5"><MapPanel reports={reports} selected={selected} /><p className="flex gap-2 rounded-xl border border-amber-200 bg-amber-50 px-4 py-3 text-xs leading-relaxed text-amber-900"><Info size={16} className="mt-0.5 shrink-0" />This is a fallback route visualization for Demo Mode. Safety scores are informational estimates, not a guarantee that any route is safe.</p></div>
        <aside className="space-y-3">
          {routeOptions.map((route) => <RouteCard key={route.id} route={route} active={route.id === selected.id} onClick={() => onChangeRoute(route)} />)}
          <button onClick={onReport} className="flex w-full items-center justify-between rounded-2xl border border-dashed border-moss/30 bg-white p-4 text-left text-sm font-bold text-moss transition hover:bg-sage/30"><span className="flex items-center gap-2"><Flag size={18} /> See or add a safety report</span><ChevronRight size={18} /></button>
        </aside>
      </div>
      <Dashboard trip={trip ?? { start: 'City Library', destination: 'Harbor Station', route: selected }} reports={reports} />
    </section>
  </>
}

function RouteCard({ route, active, onClick }: { route: RouteOption; active: boolean; onClick: () => void }) {
  const state = route.safetyScore >= 80 ? 'Safer' : route.safetyScore >= 60 ? 'Moderate' : 'Higher risk'
  return <button onClick={onClick} className={`relative w-full overflow-hidden rounded-2xl border p-4 text-left transition focus:outline-none focus:ring-4 focus:ring-moss/15 ${active ? 'border-moss bg-moss text-white shadow-lg shadow-moss/15' : 'border-moss/12 bg-white hover:border-moss/35 hover:shadow-md'}`}>
    {route.recommended && <span className={`mb-3 inline-flex items-center gap-1 rounded-full px-2.5 py-1 text-[10px] font-extrabold uppercase tracking-wider ${active ? 'bg-lime text-moss' : 'bg-sage text-moss'}`}><Sparkles size={12} /> Recommended</span>}
    <div className="flex items-start justify-between gap-3"><div><h3 className="font-extrabold">{route.name}</h3><p className={`mt-1 text-xs ${active ? 'text-white/65' : 'text-ink/50'}`}>{route.reason}</p></div><ScoreCircle score={route.safetyScore} small inverse={active} /></div>
    <div className={`mt-4 flex items-center gap-4 border-t pt-3 text-xs font-bold ${active ? 'border-white/15 text-white/75' : 'border-moss/10 text-ink/60'}`}><span className="inline-flex items-center gap-1"><Footprints size={14} />{route.distance}</span><span className="inline-flex items-center gap-1"><Clock3 size={14} />{route.duration}</span><span className="ml-auto">{state}</span></div>
  </button>
}

function MapPanel({ reports, selected }: { reports: SafetyReport[]; selected: RouteOption }) {
  const reportPoints = [[145, 194], [283, 180], [352, 113], [208, 245], [395, 87]]
  return <div className="relative min-h-[390px] overflow-hidden rounded-3xl border border-moss/10 bg-[#d7e8dd] shadow-float sm:min-h-[470px]">
    <svg viewBox="0 0 470 310" className="absolute inset-0 h-full w-full" preserveAspectRatio="xMidYMid slice" aria-label="Demo route visualization" role="img">
      <defs><pattern id="grid" width="38" height="38" patternUnits="userSpaceOnUse"><path d="M 38 0 L 0 0 0 38" fill="none" stroke="#87aa9b" strokeOpacity=".24" strokeWidth="1" /></pattern></defs>
      <rect width="470" height="310" fill="#d7e8dd" /><rect width="470" height="310" fill="url(#grid)" />
      <path d="M-20 75 C95 44 112 100 190 80 S329 15 490 38" fill="none" stroke="#f6f0dc" strokeWidth="27" strokeLinecap="round" /><path d="M-20 75 C95 44 112 100 190 80 S329 15 490 38" fill="none" stroke="#c6bfab" strokeOpacity=".35" strokeWidth="1.5" />
      <path d="M54 340 C86 258 86 205 150 162 S215 78 265-20" fill="none" stroke="#f6f0dc" strokeWidth="31" strokeLinecap="round" /><path d="M54 340 C86 258 86 205 150 162 S215 78 265-20" fill="none" stroke="#c6bfab" strokeOpacity=".35" strokeWidth="1.5" />
      <path d="M-10 256 C130 206 186 250 253 225 S370 210 493 168" fill="none" stroke="#ecf3e6" strokeWidth="18" strokeLinecap="round" />
      <path d="M29 270 C75 225 110 234 150 203 S221 177 250 146 S305 129 334 96 S399 75 438 44" fill="none" stroke="#ffffff" strokeOpacity=".7" strokeWidth="9" strokeLinecap="round" />
      {routeOptions.map((route) => <path key={route.id} d={route.path} fill="none" stroke={route.id === selected.id ? '#137866' : route.id === 'quick' ? '#d89d26' : '#d45e53'} strokeOpacity={route.id === selected.id ? 1 : .64} strokeWidth={route.id === selected.id ? 7 : 4} strokeLinecap="round" strokeLinejoin="round" />)}
      {reports.slice(0, 5).map((report, index) => { const [x, y] = reportPoints[index]; return <g key={report.id} transform={`translate(${x} ${y})`}><circle r="13" fill="#fff" fillOpacity=".94" /><circle r="8" fill={report.severity === 'High' ? '#d85c50' : report.severity === 'Medium' ? '#d89d26' : '#3a82a5'} /><path d="M-2 -3 L2 -3 L2 2 L-2 2 Z" fill="white" /></g> })}
      <g transform="translate(34 260)"><circle r="14" fill="#fff" /><circle r="8" fill="#0b3730" /><circle r="3" fill="#b6eb77" /></g>
      <g transform="translate(436 43)"><path d="M0-17 C8-17 14-11 14-3 C14 8 0 18 0 18 C0 18-14 8-14-3 C-14-11-8-17 0-17Z" fill="#ec7063" stroke="white" strokeWidth="3" /><circle cy="-3" r="4" fill="white" /></g>
    </svg>
    <div className="absolute left-4 top-4 rounded-xl border border-white/65 bg-white/90 px-3 py-2 shadow-sm backdrop-blur"><p className="text-[10px] font-extrabold uppercase tracking-wider text-moss/55">MAP MODE</p><p className="mt-0.5 text-xs font-bold text-moss">Demo route visualization</p></div>
    <div className="absolute bottom-4 left-4 right-4 flex flex-wrap gap-x-4 gap-y-2 rounded-xl bg-moss/90 px-3.5 py-2.5 text-[11px] font-semibold text-white shadow-lg backdrop-blur"><span className="inline-flex items-center gap-1.5"><i className="h-2.5 w-2.5 rounded-full bg-[#137866] ring-2 ring-white" />Selected route</span><span className="inline-flex items-center gap-1.5"><i className="h-2.5 w-2.5 rounded-full bg-coral ring-2 ring-white" />Destination</span><span className="inline-flex items-center gap-1.5"><i className="h-2.5 w-2.5 rounded-full bg-amber-500 ring-2 ring-white" />Community reports</span></div>
  </div>
}

function Dashboard({ trip, reports }: { trip: Trip; reports: SafetyReport[] }) {
  const route = trip.route
  return <section className="mt-14"><div className="flex flex-wrap items-end justify-between gap-3"><div><p className="eyebrow">CURRENT TRIP</p><h2 className="mt-2 text-2xl font-extrabold tracking-tight text-moss">Your safety snapshot</h2></div><span className="text-xs text-ink/45">Updated with Community/Demo Safety Data</span></div>
    <div className="mt-6 grid gap-5 lg:grid-cols-[1.15fr_.85fr]">
      <div className="rounded-3xl bg-moss p-6 text-white shadow-float sm:p-7"><div className="flex flex-wrap items-start justify-between gap-6"><div><p className="text-xs font-bold uppercase tracking-widest text-lime">Recommended route</p><h3 className="mt-2 text-2xl font-extrabold">{route.name}</h3><p className="mt-2 max-w-md text-sm leading-relaxed text-white/70">Recommended because this route has {route.lightingScore >= 80 ? 'better' : 'moderate'} lighting, {route.crowdScore >= 75 ? 'higher' : 'lower'} activity and fewer community safety reports.</p></div><ScoreCircle score={route.safetyScore} inverse /></div>
        <div className="mt-7 grid grid-cols-2 gap-3 border-t border-white/15 pt-5 sm:grid-cols-4"><Metric label="Start" value={trip.start} compact /><Metric label="Destination" value={trip.destination} compact /><Metric label="Distance" value={route.distance} /><Metric label="ETA" value={route.duration} /></div></div>
      <div className="rounded-3xl border border-moss/10 bg-white p-6 shadow-sm"><h3 className="font-extrabold text-moss">Safety insights</h3><div className="mt-5 space-y-4"><Insight icon={<Lightbulb size={17} />} label="Lighting" value={route.lightingScore} /><Insight icon={<Users size={17} />} label="Crowd / activity" value={route.crowdScore} /><Insight icon={<Flag size={17} />} label="Reports nearby" value={Math.max(route.reports, reports.length)} suffix=" reports" /></div></div>
    </div>
  </section>
}

function ReportsPage({ reports, onSubmit }: { reports: SafetyReport[]; onSubmit: (report: SafetyReport) => void }) {
  const [location, setLocation] = useState('')
  const [category, setCategory] = useState<ReportCategory>('Poor lighting')
  const [description, setDescription] = useState('')
  const [severity, setSeverity] = useState<Severity>('Medium')
  const [error, setError] = useState('')
  const submit = (e: React.FormEvent) => {
    e.preventDefault()
    if (location.trim().length < 2) return setError('Add a location so your report can be useful to the community.')
    if (description.trim().length < 8) return setError('Please add a short description (at least 8 characters).')
    onSubmit({ id: makeId(), latitude: 40.713 + Math.random() / 120, longitude: -74.005 + Math.random() / 100, location: location.trim(), category, description: description.trim(), severity, createdAt: 'Just now' })
    setLocation(''); setDescription(''); setCategory('Poor lighting'); setSeverity('Medium'); setError('')
  }
  return <>
    <section className="border-b border-moss/10 bg-white py-10 sm:py-14"><div className="mx-auto max-w-7xl px-5 sm:px-8"><p className="eyebrow">COMMUNITY SAFETY REPORTS</p><h1 className="mt-2 max-w-2xl text-3xl font-black tracking-tight text-moss sm:text-4xl">Share what you notice.</h1><p className="mt-4 max-w-2xl text-sm leading-relaxed text-ink/60">Reports are stored in this browser for the demo and labeled as Community/Demo Safety Data. They are not reviewed emergency reports.</p></div></section>
    <section className="mx-auto grid max-w-7xl gap-8 px-5 py-10 sm:px-8 lg:grid-cols-[.85fr_1.15fr] lg:py-14">
      <form id="report-form" onSubmit={submit} className="h-fit rounded-3xl border border-moss/10 bg-white p-5 shadow-float sm:p-7" noValidate><div className="flex items-start justify-between gap-3"><div><h2 className="text-xl font-extrabold text-moss">Report an unsafe spot</h2><p className="mt-1 text-xs leading-relaxed text-ink/50">For immediate danger, use the SOS button instead.</p></div><span className="grid h-10 w-10 place-items-center rounded-xl bg-rose-50 text-coral"><Flag size={19} /></span></div>
        <div className="mt-6 space-y-4"><FormField label="Location"><input value={location} onChange={(e) => setLocation(e.target.value)} placeholder="e.g. Oak Street underpass" className="field" /></FormField><FormField label="What happened?"><select value={category} onChange={(e) => setCategory(e.target.value as ReportCategory)} className="field">{reportCategories.map((item) => <option key={item}>{item}</option>)}</select></FormField><FormField label="Description"><textarea value={description} onChange={(e) => setDescription(e.target.value)} placeholder="Share a brief, factual description…" rows={4} className="field resize-y" /></FormField><FormField label="Severity (optional)"><div className="grid grid-cols-3 gap-2">{(['Low', 'Medium', 'High'] as Severity[]).map((level) => <button key={level} type="button" onClick={() => setSeverity(level)} className={`min-h-10 rounded-lg border text-xs font-extrabold transition ${severity === level ? severityStyles[level] : 'border-moss/10 text-ink/50 hover:bg-sand'}`}>{level}</button>)}</div></FormField></div>
        {error && <p role="alert" className="mt-4 flex gap-2 rounded-lg bg-rose-50 p-3 text-xs font-semibold text-rose-800"><AlertTriangle size={15} className="shrink-0" />{error}</p>}<button type="submit" className="mt-5 inline-flex min-h-12 w-full items-center justify-center gap-2 rounded-xl bg-moss px-4 text-sm font-extrabold text-white transition hover:bg-[#145146] focus:outline-none focus:ring-4 focus:ring-moss/20"><Plus size={18} /> Submit report</button>
      </form>
      <div><div className="mb-5 flex items-end justify-between gap-4"><div><h2 className="text-xl font-extrabold text-moss">Recent community reports</h2><p className="mt-1 text-xs text-ink/50">Visible for this local demo session</p></div><span className="rounded-full bg-sage px-3 py-1 text-xs font-bold text-moss">{reports.length} reports</span></div><div className="grid gap-3 sm:grid-cols-2">{reports.map((report) => <ReportCard key={report.id} report={report} />)}</div></div>
    </section>
  </>
}

function ContactsPage({ contacts, onChange, onToast }: { contacts: TrustedContact[]; onChange: (next: TrustedContact[]) => void; onToast: (toast: NonNullable<Toast>) => void }) {
  const [name, setName] = useState('')
  const [phone, setPhone] = useState('')
  const [editing, setEditing] = useState<string | null>(null)
  const [error, setError] = useState('')
  const submit = (event: React.FormEvent) => {
    event.preventDefault()
    const cleanName = name.trim(), cleanPhone = phone.trim()
    if (cleanName.length < 2) return setError('Enter a name for this trusted contact.')
    if (cleanPhone.replace(/\D/g, '').length < 6) return setError('Enter a valid phone number including its area or country code.')
    if (editing) onChange(contacts.map((item) => item.id === editing ? { ...item, name: cleanName, phone: cleanPhone } : item))
    else onChange([{ id: makeId(), name: cleanName, phone: cleanPhone }, ...contacts])
    setName(''); setPhone(''); setEditing(null); setError(''); onToast({ kind: 'success', message: editing ? 'Trusted contact updated.' : 'Trusted contact saved for your demo.' })
  }
  const edit = (contact: TrustedContact) => { setName(contact.name); setPhone(contact.phone); setEditing(contact.id); setError(''); window.scrollTo({ top: 0, behavior: 'smooth' }) }
  const remove = (id: string) => { onChange(contacts.filter((item) => item.id !== id)); if (editing === id) { setEditing(null); setName(''); setPhone('') }; onToast({ kind: 'success', message: 'Trusted contact removed.' }) }
  return <>
    <section className="border-b border-moss/10 bg-white py-10 sm:py-14"><div className="mx-auto max-w-7xl px-5 sm:px-8"><p className="eyebrow">TRUSTED CONTACTS</p><h1 className="mt-2 text-3xl font-black tracking-tight text-moss sm:text-4xl">Keep your people close.</h1><p className="mt-4 max-w-2xl text-sm leading-relaxed text-ink/60">Save someone you can contact from the SOS panel. Contacts are kept in this browser only for the demo.</p></div></section>
    <section className="mx-auto grid max-w-7xl gap-8 px-5 py-10 sm:px-8 lg:grid-cols-[.8fr_1.2fr] lg:py-14"><form onSubmit={submit} className="h-fit rounded-3xl border border-moss/10 bg-white p-6 shadow-float" noValidate><div className="flex items-center justify-between"><h2 className="text-xl font-extrabold text-moss">{editing ? 'Edit contact' : 'Add a contact'}</h2><span className="grid h-10 w-10 place-items-center rounded-xl bg-sage text-moss"><HeartHandshake size={19} /></span></div><div className="mt-6 space-y-4"><FormField label="Contact name"><input className="field" value={name} onChange={(e) => setName(e.target.value)} placeholder="e.g. Maya Patel" /></FormField><FormField label="Phone number"><input className="field" value={phone} onChange={(e) => setPhone(e.target.value)} placeholder="e.g. +91 98765 43210" inputMode="tel" /></FormField></div>{error && <p role="alert" className="mt-4 flex gap-2 rounded-lg bg-rose-50 p-3 text-xs font-semibold text-rose-800"><AlertTriangle size={15} className="shrink-0" />{error}</p>}<div className="mt-5 flex gap-2"><button className="min-h-12 flex-1 rounded-xl bg-moss px-4 text-sm font-extrabold text-white transition hover:bg-[#145146]">{editing ? 'Save changes' : 'Save contact'}</button>{editing && <button type="button" onClick={() => { setEditing(null); setName(''); setPhone(''); setError('') }} className="min-h-12 rounded-xl border border-moss/15 px-4 text-sm font-bold text-moss hover:bg-sand">Cancel</button>}</div></form>
      <div><div className="mb-5 flex items-center justify-between"><div><h2 className="text-xl font-extrabold text-moss">Your trusted contacts</h2><p className="mt-1 text-xs text-ink/50">Ready for the SOS panel</p></div><span className="rounded-full bg-sage px-3 py-1 text-xs font-bold text-moss">{contacts.length} saved</span></div>{contacts.length ? <div className="grid gap-3 sm:grid-cols-2">{contacts.map((contact) => <article key={contact.id} className="rounded-2xl border border-moss/10 bg-white p-5 shadow-sm"><div className="flex items-start justify-between gap-3"><span className="grid h-10 w-10 place-items-center rounded-xl bg-sage text-moss"><Users size={18} /></span><div className="flex gap-1"><button onClick={() => edit(contact)} className="rounded-lg px-2 py-1.5 text-xs font-bold text-moss hover:bg-sage">Edit</button><button onClick={() => remove(contact.id)} className="rounded-lg px-2 py-1.5 text-xs font-bold text-rose-700 hover:bg-rose-50">Remove</button></div></div><h3 className="mt-4 font-extrabold text-moss">{contact.name}</h3><a href={`tel:${contact.phone.replace(/[^+\d]/g, '')}`} className="mt-1 inline-flex items-center gap-1.5 text-sm font-semibold text-ink/60 hover:text-moss"><Phone size={14} />{contact.phone}</a></article>)}</div> : <EmptyContacts />}</div></section>
  </>
}

function SafetyScorePage() {
  return <><section className="border-b border-moss/10 bg-white py-10 sm:py-14"><div className="mx-auto max-w-7xl px-5 sm:px-8"><p className="eyebrow">ABOUT SAFETY SCORE</p><h1 className="mt-2 max-w-2xl text-3xl font-black tracking-tight text-moss sm:text-4xl">Clear factors. No false certainty.</h1><p className="mt-4 max-w-2xl text-sm leading-relaxed text-ink/60">The score is a transparent, demo-only route comparison tool—not an official safety rating, real-time risk prediction, or guarantee of safety.</p></div></section>
    <section className="mx-auto max-w-7xl px-5 py-12 sm:px-8 lg:py-16"><div className="grid gap-6 lg:grid-cols-[.8fr_1.2fr]"><aside className="rounded-3xl bg-moss p-7 text-white shadow-float"><p className="text-xs font-extrabold uppercase tracking-widest text-lime">THE SCALE</p><h2 className="mt-2 text-2xl font-extrabold">A route score from 0–100</h2><div className="mt-8 space-y-5"><ScaleRow score="80–100" label="Safer" color="bg-lime" /><ScaleRow score="60–79" label="Moderate" color="bg-amber-400" /><ScaleRow score="Below 60" label="Higher risk" color="bg-coral" /></div><p className="mt-8 border-t border-white/15 pt-5 text-xs leading-relaxed text-white/60">Scores offer a starting point for comparing available routes. Use your judgment, stay aware of your surroundings, and call local emergency services when needed.</p></aside><div className="rounded-3xl border border-moss/10 bg-white p-6 sm:p-8"><h2 className="text-2xl font-extrabold text-moss">How is this calculated?</h2><p className="mt-2 text-sm leading-relaxed text-ink/60">We combine four route factors. In Demo Mode, the values are simulated Community/Demo Safety Data so judges can explore the product flow.</p><div className="mt-7 space-y-5"><WeightRow icon={<Lightbulb size={20} />} title="Lighting" weight="30%" text="Streetlight coverage and generally well-lit route segments." /><WeightRow icon={<Users size={20} />} title="Crowd / activity" weight="25%" text="General evening activity and likelihood of nearby people." /><WeightRow icon={<Flag size={20} />} title="Report history" weight="30%" text="Recency, frequency and severity of nearby community reports." /><WeightRow icon={<Navigation size={20} />} title="Route environment" weight="15%" text="Distance, directness and environmental route characteristics." /></div></div></div></section>
  </>
}

function SOSModal({ contacts, onClose, onToast }: { contacts: TrustedContact[]; onClose: () => void; onToast: (toast: NonNullable<Toast>) => void }) {
  const [locationStatus, setLocationStatus] = useState<string | null>(null)
  const [sharing, setSharing] = useState(false)
  const share = async () => {
    setSharing(true)
    const message = 'SafeRoute Demo Mode: I am sharing my current location. Please check in with me.'
    try {
      if (navigator.share) { await navigator.share({ title: 'SafeRoute check-in', text: message }); onToast({ kind: 'success', message: 'Share sheet opened. Choose how you want to send your check-in.' }) }
      else { await navigator.clipboard?.writeText(message); onToast({ kind: 'success', message: 'Demo check-in copied. Your browser does not support native sharing.' }) }
    } catch { onToast({ kind: 'error', message: 'Location sharing was cancelled or unavailable. No message was sent.' }) }
    setSharing(false)
  }
  const getLocation = () => {
    if (!navigator.geolocation) return setLocationStatus('Location is unavailable in this browser. Demo Mode has not shared anything.')
    setLocationStatus('Requesting your permission…')
    navigator.geolocation.getCurrentPosition(
      (position) => setLocationStatus(`Location ready in Demo Mode: ${position.coords.latitude.toFixed(4)}, ${position.coords.longitude.toFixed(4)}. Nothing was sent.`),
      () => setLocationStatus('We could not access your location. Check browser permission and try again. Nothing was shared.'),
      { enableHighAccuracy: true, timeout: 10000 },
    )
  }
  const trusted = contacts[0]
  return <div className="fixed inset-0 z-50 grid place-items-end bg-moss/50 p-0 backdrop-blur-sm sm:place-items-center sm:p-5" role="dialog" aria-modal="true" aria-labelledby="sos-title"><div className="w-full max-w-lg rounded-t-3xl bg-white p-5 shadow-2xl sm:rounded-3xl sm:p-7"><div className="flex items-start justify-between gap-4"><div className="flex items-start gap-3"><span className="grid h-11 w-11 shrink-0 place-items-center rounded-2xl bg-rose-100 text-coral"><Signal size={22} /></span><div><p className="text-xs font-extrabold uppercase tracking-widest text-coral">EMERGENCY OPTIONS</p><h2 id="sos-title" className="mt-1 text-2xl font-black text-moss">Are you safe right now?</h2></div></div><button onClick={onClose} className="grid h-10 w-10 place-items-center rounded-xl text-ink/50 hover:bg-sand" aria-label="Close SOS options"><X size={21} /></button></div><p className="mt-4 text-sm leading-relaxed text-ink/65">Choose an action below. SafeRoute will never call or message anyone automatically.</p>
    <div className="mt-6 space-y-3"><a href="tel:112" onClick={() => onToast({ kind: 'success', message: 'Opening your phone’s call action. You decide whether to place the call.' })} className="flex min-h-14 items-center justify-between rounded-2xl bg-coral px-4 text-sm font-extrabold text-white transition hover:bg-[#d85c50]"><span className="flex items-center gap-3"><Phone size={19} /> Call emergency services</span><ArrowDownRight size={18} /></a><a href={trusted ? `tel:${trusted.phone.replace(/[^+\d]/g, '')}` : '#trusted-contact'} onClick={(event) => { if (!trusted) { event.preventDefault(); onToast({ kind: 'error', message: 'Add a trusted contact first. No call was placed.' }) } }} className="flex min-h-14 items-center justify-between rounded-2xl border border-moss/15 px-4 text-sm font-extrabold text-moss transition hover:bg-sage/40"><span className="flex items-center gap-3"><HeartHandshake size={19} /> {trusted ? `Call ${trusted.name}` : 'Call trusted contact'}</span><ArrowDownRight size={18} /></a><button onClick={getLocation} className="flex min-h-14 w-full items-center justify-between rounded-2xl border border-moss/15 px-4 text-left text-sm font-extrabold text-moss transition hover:bg-sage/40"><span className="flex items-center gap-3"><MapPin size={19} /> Get current location</span><ChevronRight size={18} /></button><button disabled={sharing} onClick={() => void share()} className="flex min-h-14 w-full items-center justify-between rounded-2xl border border-moss/15 px-4 text-left text-sm font-extrabold text-moss transition hover:bg-sage/40 disabled:opacity-60"><span className="flex items-center gap-3"><Copy size={19} /> {sharing ? 'Preparing share…' : 'Share a check-in'}</span><ChevronRight size={18} /></button></div>{locationStatus && <p className="mt-4 rounded-xl bg-sage/60 px-3 py-2.5 text-xs font-medium leading-relaxed text-moss">{locationStatus}</p>}<p className="mt-5 text-center text-[11px] leading-relaxed text-ink/45">Demo Mode: actual emergency response and device capabilities vary. If you are in immediate danger, call your local emergency number.</p></div></div>
}

function ScoreCircle({ score, small = false, inverse = false }: { score: number; small?: boolean; inverse?: boolean }) { const safe = score >= 80 ? 'text-emerald-600' : score >= 60 ? 'text-amber-600' : 'text-rose-500'; return <div className={`relative grid shrink-0 place-items-center rounded-full border-4 ${small ? 'h-14 w-14 text-sm' : 'h-24 w-24 text-2xl'} ${inverse ? 'border-lime/45 bg-white/10 text-white' : `border-current bg-white ${safe}`}`}><span className="font-black tracking-tight">{score}</span><span className={`absolute ${small ? '-bottom-3 text-[8px]' : '-bottom-4 text-[10px]'} whitespace-nowrap rounded-full px-1.5 py-0.5 font-bold ${inverse ? 'bg-lime text-moss' : 'bg-sand text-ink/65'}`}>{score >= 80 ? 'Safer' : score >= 60 ? 'Moderate' : 'Higher risk'}</span></div> }
function Metric({ label, value, compact = false }: { label: string; value: string; compact?: boolean }) { return <div><p className="text-[10px] font-bold uppercase tracking-wider text-white/45">{label}</p><p className={`mt-1 font-extrabold ${compact ? 'truncate text-sm' : 'text-base'}`} title={value}>{value}</p></div> }
function Insight({ icon, label, value, suffix = '' }: { icon: React.ReactNode; label: string; value: number; suffix?: string }) { return <div><div className="flex items-center justify-between gap-3"><span className="flex items-center gap-2 text-sm font-bold text-moss"><span className="text-moss/70">{icon}</span>{label}</span><span className="text-sm font-extrabold text-moss">{value}{suffix}</span></div><div className="mt-2 h-2 overflow-hidden rounded-full bg-sage"><div className="h-full rounded-full bg-moss" style={{ width: `${Math.min(value, 100)}%` }} /></div></div> }
function ReportCard({ report }: { report: SafetyReport }) { return <article className="rounded-2xl border border-moss/10 bg-white p-4 shadow-sm"><div className="flex items-start justify-between gap-3"><span className="grid h-9 w-9 shrink-0 place-items-center rounded-xl bg-sage text-moss"><Flag size={17} /></span><span className={`rounded-full px-2.5 py-1 text-[10px] font-extrabold ring-1 ${severityStyles[report.severity]}`}>{report.severity}</span></div><h3 className="mt-4 font-extrabold text-moss">{report.category}</h3><p className="mt-1 flex items-center gap-1 text-xs font-semibold text-ink/55"><MapPin size={12} />{report.location}</p><p className="mt-3 line-clamp-2 text-xs leading-relaxed text-ink/60">{report.description}</p><div className="mt-4 flex items-center justify-between border-t border-moss/8 pt-3 text-[10px] font-bold text-ink/40"><span>{report.createdAt}</span>{report.demo && <span>DEMO DATA</span>}</div></article> }
function FormField({ label, children }: { label: string; children: React.ReactNode }) { return <label className="block"><span className="mb-1.5 block text-xs font-bold uppercase tracking-wider text-ink/55">{label}</span>{children}</label> }
function EmptyContacts() { return <div className="grid min-h-64 place-items-center rounded-3xl border border-dashed border-moss/20 bg-white p-8 text-center"><div><span className="mx-auto grid h-12 w-12 place-items-center rounded-2xl bg-sage text-moss"><HeartHandshake size={22} /></span><h3 className="mt-4 font-extrabold text-moss">No trusted contacts yet</h3><p className="mt-2 max-w-xs text-sm leading-relaxed text-ink/55">Add someone you’d want to reach quickly from the SOS panel.</p></div></div> }
function WeightRow({ icon, title, weight, text }: { icon: React.ReactNode; title: string; weight: string; text: string }) { return <div className="flex gap-4 border-b border-moss/8 pb-5 last:border-0"><span className="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-sage text-moss">{icon}</span><div className="min-w-0 flex-1"><div className="flex items-center justify-between gap-2"><h3 className="font-extrabold text-moss">{title}</h3><span className="rounded-full bg-moss px-2.5 py-1 text-xs font-bold text-lime">{weight}</span></div><p className="mt-1 text-sm leading-relaxed text-ink/55">{text}</p></div></div> }
function ScaleRow({ score, label, color }: { score: string; label: string; color: string }) { return <div className="flex items-center gap-3"><span className={`h-3 w-3 rounded-full ${color}`} /><div className="flex min-w-0 flex-1 justify-between text-sm"><span className="font-bold text-white/65">{score}</span><span className="font-extrabold">{label}</span></div></div> }
function MiniStat({ icon, title, text }: { icon: React.ReactNode; title: string; text: string }) { return <article className="bg-white p-5 sm:p-6"><span className="grid h-10 w-10 place-items-center rounded-xl bg-sage text-moss">{icon}</span><h3 className="mt-4 font-extrabold text-moss">{title}</h3><p className="mt-1 text-sm leading-relaxed text-ink/55">{text}</p></article> }
function Feature({ icon, title, text }: { icon: React.ReactNode; title: string; text: string }) { return <div className="rounded-2xl border border-moss/10 bg-white p-5"><span className="grid h-9 w-9 place-items-center rounded-xl bg-sage text-moss">{icon}</span><h3 className="mt-3 font-extrabold text-moss">{title}</h3><p className="mt-1 text-sm leading-relaxed text-ink/55">{text}</p></div> }
function ToastMessage({ toast, onClose }: { toast: NonNullable<Toast>; onClose: () => void }) { return <div className="fixed bottom-5 right-5 z-[60] flex max-w-sm items-start gap-3 rounded-2xl border border-moss/10 bg-white p-4 shadow-2xl" role="status"><span className={`grid h-9 w-9 shrink-0 place-items-center rounded-xl ${toast.kind === 'success' ? 'bg-sage text-moss' : 'bg-rose-50 text-coral'}`}>{toast.kind === 'success' ? <ShieldCheck size={18} /> : <AlertTriangle size={18} />}</span><p className="pt-1 text-sm font-semibold leading-relaxed text-moss">{toast.message}</p><button onClick={onClose} className="text-ink/40 hover:text-moss" aria-label="Dismiss notification"><X size={17} /></button></div> }
function Footer({ onNavigate }: { onNavigate: (page: Page) => void }) { return <footer className="border-t border-moss/10 bg-white"><div className="mx-auto flex max-w-7xl flex-col gap-5 px-5 py-8 sm:flex-row sm:items-center sm:justify-between sm:px-8"><div className="flex items-center gap-2 font-extrabold text-moss"><span className="grid h-7 w-7 place-items-center rounded-lg bg-moss text-lime"><ShieldCheck size={15} /></span>SafeRoute</div><p className="max-w-xl text-xs leading-relaxed text-ink/45">Demo Mode uses Community/Demo Safety Data. SafeRoute does not guarantee safety or replace emergency services.</p><button onClick={() => onNavigate('score')} className="text-left text-xs font-bold text-moss underline-offset-4 hover:underline">About the score</button></div></footer> }

export default App

@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Outfit:wght@500;600;700;800;900&display=swap');

@tailwind base;
@tailwind components;
