  background-size: 25px 25px;
  mask-image: linear-gradient(90deg, transparent 2%, black 30%, black 73%, transparent 98%);
}

@media (prefers-reduced-motion: no-preference) {
  .shadow-float { animation: settled 500ms ease-out both; }
  @keyframes settled { from { opacity: .7; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }
}

